{
        // Arrange
        var channel = new AnalogChannel(0);
        var tasks = new List<Task>();

        // Act
        for (int i = 0; i < 100; i++)
        {
            var value = i;
            tasks.Add(Task.Run(() => channel.SetActiveSample(value, DateTime.UtcNow)));
        }

        await Task.WhenAll(tasks.ToArray());

        // Assert
        Assert.NotNull(channel.ActiveSample);
    }
